/**
 * FIX dictionary loader.
 *
 * Dictionaries are versioned JSON documents generated by
 * tools/quickfix_to_json.py and served at /dictionaries/<VERSION>.json.
 * This module fetches and caches them and provides tag/enum/message
 * translation for the UI. The default dictionary (FIX.4.2) is loaded at
 * module evaluation via top-level await; per-session dictionaries load on
 * demand through loadDictionary(). Custom dictionaries (user-defined names
 * outside STANDARD_VERSIONS) resolve through the fix_cmd service instead —
 * the server merges deltas over their base so client and engine agree.
 */

export const STANDARD_VERSIONS = [
    "FIX.4.0",
    "FIX.4.1",
    "FIX.4.2",
    "FIX.4.3",
    "FIX.4.4",
    "FIX.5.0",
    "FIX.5.0SP1",
    "FIX.5.0SP2",
];

export class FixDictionary {
    constructor(doc = {}) {
        this.version = doc.version || "";
        this.beginString = doc.begin_string || this.version;
        this.fields = doc.fields || {};
        this.enums = doc.enums || {};
        this.messages = doc.messages || {};
        this.header = doc.header || [];
        this.trailer = doc.trailer || [];
        this.groups = doc.groups || {};
        this._headerSet = new Set(this.header);
        this._trailerSet = new Set(this.trailer);
    }

    tagName(tag) {
        const f = this.fields[tag];
        return f ? f.name : String(tag);
    }

    fieldType(tag) {
        const f = this.fields[tag];
        return f ? f.type : "STRING";
    }

    enumName(tag, value) {
        const e = this.enums[tag];
        return e && e[value] !== undefined ? e[value] : String(value);
    }

    msgTypeName(code) {
        const m = this.messages[code];
        return m ? m.name : String(code);
    }

    group(tag) {
        return this.groups[tag] || null;
    }

    isHeader(tag) {
        return this._headerSet.has(tag);
    }

    isTrailer(tag) {
        return this._trailerSet.has(tag);
    }
}

const EMPTY = new FixDictionary({});
const cache = new Map(); // version -> Promise<FixDictionary>

/**
 * Fetch (or reuse) the dictionary for a FIX version. Never rejects: an
 * unknown version resolves to an empty dictionary that passes raw values
 * through untranslated.
 *
 * @param {string} version  e.g. "FIX.4.2"
 * @returns {Promise<FixDictionary>}
 */
export function loadDictionary(version = "FIX.4.2") {
    if (!cache.has(version)) {
        const source = STANDARD_VERSIONS.includes(version)
            ? fetch(`/dictionaries/${version.replaceAll(".", "")}.json`).then((r) => {
                if (!r.ok) throw new Error(`HTTP ${r.status}`);
                return r.json();
            })
            : import("/mkui/src/mkio-bridge.js")
                .then(({ ensureMkio }) => ensureMkio())
                .then((client) =>
                    client.send("fix_cmd", { command: "get_dictionary", name: version },
                                { op: "get_dictionary" }))
                .then((res) => res.dictionary);
        const promise = source
            .then((doc) => new FixDictionary(doc))
            .catch((err) => {
                console.warn(`mkfix: no dictionary for ${version}:`, err.message || err);
                return EMPTY;
            });
        cache.set(version, promise);
    }
    return cache.get(version);
}

/** Drop a cached dictionary so the next loadDictionary() refetches it. */
export function invalidateDictionary(version) {
    cache.delete(version);
}

/**
 * Resolve a delta document over a base document; the delta wins. Mirrors
 * merge_dictionary in mkfix/fix/dictionary.py: fields/messages/groups merge
 * per tag (null removes), enums merge per tag per code (union, null removes),
 * header/trailer/begin_string replace wholesale when present.
 */
export function mergeDictionary(base, delta) {
    const data = {
        version: delta.version ?? base.version ?? "",
        begin_string: delta.begin_string ?? base.begin_string ?? "",
        header: [...(delta.header ?? base.header ?? [])],
        trailer: [...(delta.trailer ?? base.trailer ?? [])],
        fields: {}, enums: {}, messages: {}, groups: {},
    };
    for (const key of ["fields", "messages", "groups"]) {
        const merged = { ...(base[key] || {}) };
        for (const [tag, entry] of Object.entries(delta[key] || {})) {
            if (entry === null) delete merged[tag];
            else merged[tag] = entry;
        }
        data[key] = merged;
    }
    const enums = {};
    for (const [tag, values] of Object.entries(base.enums || {})) {
        enums[tag] = { ...values };
    }
    for (const [tag, values] of Object.entries(delta.enums || {})) {
        if (values === null) {
            delete enums[tag];
            continue;
        }
        const current = enums[tag] ?? (enums[tag] = {});
        for (const [code, name] of Object.entries(values)) {
            if (name === null) delete current[code];
            else current[code] = name;
        }
        if (!Object.keys(current).length) delete enums[tag];
    }
    data.enums = enums;
    return data;
}

/** Plain document form of a loaded FixDictionary (for local re-resolution). */
export function dictionaryToDoc(dict) {
    return {
        version: dict.version,
        begin_string: dict.beginString,
        header: dict.header,
        trailer: dict.trailer,
        fields: dict.fields,
        enums: dict.enums,
        messages: dict.messages,
        groups: dict.groups,
    };
}

export const defaultDictionary = await loadDictionary("FIX.4.2");

export function translateTag(tag, dict = defaultDictionary) {
    return dict.tagName(tag);
}

export function translateEnum(tag, value, dict = defaultDictionary) {
    return dict.enumName(tag, value);
}

export function msgTypeName(code, dict = defaultDictionary) {
    return dict.msgTypeName(code);
}

/**
 * Parse a raw FIX message into a display tree using the dictionary's group
 * metadata. Returns top-level nodes in wire order:
 *   {kind: "field", tag, value}
 *   {kind: "group", tag, value, entries: [[node, ...], ...]}
 * A group instance starts at the group's delimiter tag and ends at the next
 * delimiter or the first non-member tag; nested groups recurse. Structure is
 * a parsing concern only — unknown groups fall out flat.
 *
 * @param {string} rawMessage
 * @param {FixDictionary} dict
 * @returns {Array<object>}
 */
export function parseMessageTree(rawMessage, dict = defaultDictionary) {
    const sep = rawMessage.includes("\x01") ? "\x01" : "|";
    const pairs = [];
    for (const p of rawMessage.split(sep)) {
        const i = p.indexOf("=");
        if (i > 0) pairs.push({ tag: p.slice(0, i), value: p.slice(i + 1) });
    }

    let idx = 0;

    function node() {
        const { tag, value } = pairs[idx];
        const g = dict.group(tag);
        idx++;
        if (g && !Number.isNaN(parseInt(value, 10))) {
            return { kind: "group", tag, value, entries: groupEntries(g) };
        }
        return { kind: "field", tag, value };
    }

    function groupEntries(g) {
        const memberSet = new Set(g.members);
        const entries = [];
        while (idx < pairs.length && pairs[idx].tag === g.delim) {
            entries.push(instance(g, memberSet));
        }
        return entries;
    }

    function instance(g, memberSet) {
        const nodes = [];
        let first = true;
        while (idx < pairs.length) {
            const { tag } = pairs[idx];
            if (!memberSet.has(tag)) break;
            if (tag === g.delim && !first) break;
            first = false;
            nodes.push(node());
        }
        return nodes;
    }

    const top = [];
    while (idx < pairs.length) top.push(node());
    return top;
}

export function translateMessage(rawMessage, dict = defaultDictionary) {
    if (!rawMessage || typeof rawMessage !== "string") {
        return [];
    }

    const pairs = rawMessage.split(/\x01|\|/).filter(Boolean);
    const fields = [];

    for (const pair of pairs) {
        const eqIdx = pair.indexOf("=");
        if (eqIdx === -1) continue;

        const tag = pair.substring(0, eqIdx);
        const value = pair.substring(eqIdx + 1);
        const section = dict.isHeader(tag) ? "header"
            : dict.isTrailer(tag) ? "trailer"
            : "body";

        fields.push({
            tag,
            name: dict.tagName(tag),
            value,
            translated: dict.enumName(tag, value),
            section,
        });
    }

    return fields;
}
